import{_ as n,C as a,c as l,o as r,aj as s,G as t,w as d}from"./chunks/framework.Bfdr4H5E.js";const p="/sk/images/VWAP-Line.webp",u="/sk/images/VWAP-Standard-Deviations.webp",h="/sk/images/VWAP-How-to-Use.webp",c="/sk/images/VWAP-Accumulation.webp",m="/sk/images/VWAP-Dntrend.webp",g="/sk/images/VWAP-Uptrend.webp",P="/sk/images/VWAP-Settings.webp",v="/sk/images/Intraday-VWAP.webp",A="/sk/images/VWAP-Prev-session-values.webp",V="/sk/images/Volume-Profile-plus-Fibonacci-combination.webp",w="/sk/images/VWAP-and-VP-Fibonacci.webp",x=JSON.parse('{"title":"VWAP","description":"","frontmatter":{"outline":"deep","prev":{"text":"Reversal trades","link":"/trading-with-pav/reversal-trades"},"next":{"text":"Ensuring Survival","link":"/trading-with-pav/ensuring-survival"}},"headers":[],"relativePath":"trading-with-pav/vwap.md","filePath":"trading-with-pav/vwap.md"}'),W={name:"trading-with-pav/vwap.md"};function b(f,e,y,k,_,S){const i=a("GraphComment"),o=a("ClientOnly");return r(),l("div",null,[e[0]||(e[0]=s('<h1 id="vwap" tabindex="-1">VWAP <a class="header-anchor" href="#vwap" aria-label="Permalink to &quot;VWAP&quot;">​</a></h1><p>Lets dive into Volume Weighted Average Price i.e. VWAP.</p><div class="info custom-block"><p class="custom-block-title">Table of Contents</p><nav class="table-of-contents"><ul><li><a href="#vwap-1">VWAP</a><ul><li><a href="#basic-logic">Basic Logic</a></li><li><a href="#standard-deviations">Standard Deviations</a></li><li><a href="#vwap-usage-by-institution">VWAP usage by Institution</a></li><li><a href="#vwap-–-how-to-use">VWAP – How to use ?</a></li></ul></li><li><a href="#vwap-–-accumulation-setup">VWAP – Accumulation Setup*</a></li><li><a href="#vwap-–-trend-setup">VWAP – Trend Setup*</a></li><li><a href="#vwap-–-calculation-period">VWAP – Calculation Period</a></li><li><a href="#vwap-–-let-it-develop">VWAP – Let it develop</a></li><li><a href="#vwap-–-prev-session-values">VWAP – Prev. session values</a></li><li><a href="#vwap-volume-profile">VWAP + Volume Profile</a></li><li><a href="#comments">Comments</a></li></ul></nav></div><h2 id="vwap-1" tabindex="-1">VWAP <a class="header-anchor" href="#vwap-1" aria-label="Permalink to &quot;VWAP&quot;">​</a></h2><ul><li>One of the most commonly used algorithm of big trading institutions is Standard Average, BUT weighted by volume (= prices where big volumes got traded, are more important)</li><li>All trading instruments.</li><li>All time frames.</li></ul><p><img src="'+p+'" alt="VWAP-Line"></p><p>VWAP Line</p><h3 id="basic-logic" tabindex="-1">Basic Logic <a class="header-anchor" href="#basic-logic" aria-label="Permalink to &quot;Basic Logic&quot;">​</a></h3><ul><li>Institutions want to BUY CHEAP &amp; SELL EXPENSIVE</li><li>Institutions are looking for a</li><li>BUY when Price is BELOW VWAP, and for a</li><li>SELL when Price is ABOVE VWAP.</li><li>AND VICE VERSA:</li><li>Institutions are</li><li>NOT looking for a SELL when Price is BELOW VWAP, &amp;</li><li>NOT looking for a BUY when Price is ABOVE VWAP.</li><li>Price should return to VWAP.</li><li>It works as a magnet.</li><li>Institutional algorithms are usually set to execute trades close to VWAP.</li></ul><h3 id="standard-deviations" tabindex="-1">Standard Deviations <a class="header-anchor" href="#standard-deviations" aria-label="Permalink to &quot;Standard Deviations&quot;">​</a></h3><p><img src="'+u+'" alt="VWAP-Standard-Deviations"></p><p>VWAP with Standard Deviations</p><ul><li>In above chart Indicator shows 1st and 2nd standard deviation of VWAP.</li><li>More responsive than VWAP.</li><li>Show nicely if there is a TREND or a ROTATION.</li><li>Deviations = Support &amp; Resistance zones.</li><li>In Rotation as well as in Trend market development.</li></ul><h3 id="vwap-usage-by-institution" tabindex="-1">VWAP usage by Institution <a class="header-anchor" href="#vwap-usage-by-institution" aria-label="Permalink to &quot;VWAP usage by Institution&quot;">​</a></h3><p>When an Institution has large orders that must be filled they will often use a VWAP based algorithm to execute the order as close to VWAP as possible. By executing their order as close to VWAP as possible it indicates that they have been able to minimize the market impact of their order. Hedge funds are conscious of their market impact costs which are the costs incurred by trades so big that they will move the market.</p><p>In a simple form VWAP is used to determine value for institutional traders much in the same way a moving average works as a trading indicator. But VWAP is used more for trade analysis than trade entry. When a buy order is filled at a price better than VWAP it is good for the trader as the average transaction value is better than what everyone else in market for that time period also received. The reverse is also true for when one is selling. If a sell order is filled at a price better than VWAP the trader is selling at a higher average price than everyone else during that time period. VWAP is the measuring stick for large orders.</p><p>When price is below VWAP, institutions that are looking to buy will tend to buy at prices below VWAP as they are able to build a position that is better than the VWAP. They won’t be that willing to buy when the price is trading above VWAP as it will ruin their own average price against VWAP.</p><p>When price is above VWAP, institutions that are looking to sell or get short will try to execute their orders as they are selling at prices that they feel are better than what has been recently trading. If an institution is trying to fill an order they won’t be as willing to buy when price is trading above VWAP, they may buy some just to participate in case price never comes back to VWAP, but it will be minimal.</p><p>The interesting thing about VWAP orders is that there is no guarantee that it will be filled or that it will match VWAP.</p><p>So why is VWAP important? For an intraday trader VWAP is important because they can determine if they are selling too cheap or buying to rich. When prices start moving 1 or 2 standard deviations above VWAP and you are buying you could be buying at prices too expensive. Conversely, if you are selling and prices are 2 standard deviations below VWAP you could very well be selling too cheap. This is not to say that prices cannot move 3 and even 4 standard deviations away from VWAP because it can.</p><p>When trading with S-R plus Volume Profile zones you can lay VWAP lines on your chart to give you an indication if it trading cheap or rich. I am more prone to take buy signals when the market is trading cheap and sell signals when the market is trading rich to VWAP.</p><p>Do not think for a minute that VWAP has to revert to the mean. A market can stay above or below VWAP most of the day.</p><ul><li>VWAP is not without its limitations. As the trading day goes on the lag in VWAP become stronger.</li><li>This is because a lot of trade data has already been factored in and new trade data has less of an impact on the overall VWAP number and will tend to flatten out.</li><li>On strong trending days price will be above or below VWAP pretty much all day.</li><li>On range trading days VWAP will run through the middle of price action.</li><li>On days when important news comes into the market late in the day, that cause significant price movements on heavy volume the VWAP profile will be affected.</li><li>How an order is executed will also affect the VWAP since the average execution sits somewhere between the bid and offer spread.</li><li>To match VWAP an order would need to be a combination of limit orders and market orders.</li></ul><p>Don’t be misled into thinking that VWAP is a new excellent indicator to take trades against. As I mentioned earlier, VWAP is a way to measure a broker’s trade execution. Traders make money by buying low and selling high, not by beating VWAP.</p><h3 id="vwap-–-how-to-use" tabindex="-1">VWAP – How to use ? <a class="header-anchor" href="#vwap-–-how-to-use" aria-label="Permalink to &quot;VWAP – How to use ?&quot;">​</a></h3><p><img src="'+h+'" alt="VWAP-How-to-Use"></p><ul><li>Use VWAP as a Take Profit (works like a magnet).</li><li>Use Standard Deviations to identify rotation/trend.</li><li>Use Standard Deviations as Support &amp; Resistance zones.</li></ul><h2 id="vwap-–-accumulation-setup" tabindex="-1">VWAP – Accumulation Setup* <a class="header-anchor" href="#vwap-–-accumulation-setup" aria-label="Permalink to &quot;VWAP – Accumulation Setup*&quot;">​</a></h2><p><img src="'+c+'" alt="VWAP-Accumulation"></p><p>VWAP Accumulation Setup</p><ul><li>Identify a accumulation (VWAP and deviations go sideways)</li><li><strong>SHORT</strong> when price goes up and hits VWAP from below</li><li><strong>LONG</strong> when price goes down and hits 2nd deviation from above</li><li>A viable Take Profit is VWAP line*</li></ul><h2 id="vwap-–-trend-setup" tabindex="-1">VWAP – Trend Setup* <a class="header-anchor" href="#vwap-–-trend-setup" aria-label="Permalink to &quot;VWAP – Trend Setup*&quot;">​</a></h2><p><img src="'+m+'" alt="VWAP-Dntrend"></p><p>VWAP – In Downtrend</p><ul><li>Identify a trend (for example using VWAP deviations)</li><li>In Downtrend:</li><li>wait for pullback to 1st deviation or VWAP line.</li><li>Go <strong>SHORT</strong>.</li></ul><p><img src="'+g+'" alt="VWAP-Uptrend"></p><p>VWAP – In Uptrend</p><ul><li>Identify a trend (for example using VWAP deviations)</li><li>In Uptrend:</li><li>wait for pullback to 1st deviation or VWAP line.</li><li>Go <strong>LONG</strong>.</li></ul><h2 id="vwap-–-calculation-period" tabindex="-1">VWAP – Calculation Period <a class="header-anchor" href="#vwap-–-calculation-period" aria-label="Permalink to &quot;VWAP – Calculation Period&quot;">​</a></h2><p><img src="'+P+'" alt="VWAP-Settings"></p><p>VWAP Settings</p><ul><li>A new <strong>VWAP</strong> gets calculated every Day (or week, month, year).</li><li><strong>Intraday</strong> trading: <strong>Daily</strong>, <strong>Weekly</strong>, <strong>Monthly</strong> plots</li><li><strong>Swing</strong> trading: <strong>Monthly</strong>, <strong>Yearly</strong> plots</li><li><strong>Long</strong>–<strong>term</strong> trading: <strong>Yearly</strong> plots</li></ul><p><img src="'+v+'" alt="Intraday-VWAP"></p><p>Intraday VWAP – Top weekly plot, Bottom daily plot</p><h2 id="vwap-–-let-it-develop" tabindex="-1">VWAP – Let it develop <a class="header-anchor" href="#vwap-–-let-it-develop" aria-label="Permalink to &quot;VWAP – Let it develop&quot;">​</a></h2><ul><li>Wait until VWAP and its deviations develop before using it to create trading levels (roughly): <ol><li>Daily VWAP – 5 hours (2h)</li><li>Weekly VWAP – 2 days (1.5d)</li><li>Monthly VWAP – 10 days (7d)</li><li>Yearly VWAP – 2 months (1.5m)</li></ol></li></ul><h2 id="vwap-–-prev-session-values" tabindex="-1">VWAP – Prev. session values <a class="header-anchor" href="#vwap-–-prev-session-values" aria-label="Permalink to &quot;VWAP – Prev. session values&quot;">​</a></h2><p><img src="'+A+'" alt="VWAP-Prev-session-values"></p><p>Above Chart VWAP previous years line act as resistance and support.</p><ul><li>Work as additional Support and Resistance zones.</li><li>Use only as a confirmation. Not as standalone trading levels.</li></ul><h2 id="vwap-volume-profile" tabindex="-1">VWAP + Volume Profile <a class="header-anchor" href="#vwap-volume-profile" aria-label="Permalink to &quot;VWAP + Volume Profile&quot;">​</a></h2><ul><li>VWAP setups are a good standalone strategy BUT shine most when used with Volume Profile.</li><li>Volume Accumulation Setup or Volume Trend Setup combined with VWAP deviation form a strong long intraday support level.</li></ul><p><img src="'+V+'" alt="Volume-Profile-plus-Fibonacci-combination"></p><p>Volume Profile and Fibonacci Confluence</p><p><img src="'+w+'" alt="VWAP-and-VP-Fibonacci"></p><p>Additional VWAP Confluence at same area</p><p>That’s a wrap for Volume 5 next up is Volume 6: YOUR TRADING BUSINESS. Will explore articles related to it. Keep Practicing.</p><h2 id="comments" tabindex="-1">Comments <a class="header-anchor" href="#comments" aria-label="Permalink to &quot;Comments&quot;">​</a></h2>',58)),t(o,null,{default:d(()=>[t(i)]),_:1})])}const T=n(W,[["render",b]]);export{x as __pageData,T as default};
